<div class="eq-card"><div class="eq-title"><i class="fa fa-sign-out"></i> ENTREGA DE EQUIPAJE</div><div class="alert alert-info" style="margin-top:8px">Escanee o escriba el <b>CÓDIGO DE EQUIPAJE</b> (ej. EQ-0026-P000425). Con una sola lectura se verifica el equipaje y se habilita la confirmación de entrega.</div><div class="row"><div class="col-md-10"><label>Código de equipaje</label><input id="eq_codigo_entrega" class="form-control" placeholder="Escanee QR o escriba EQ-0026-P000425" autocomplete="off"></div><div class="col-md-2"><label>&nbsp;</label><button class="btn btn-warning btn-block" onclick="eqBuscarEntrega()">VERIFICAR</button></div></div><div id="eq_entrega_result" style="margin-top:8px"></div></div>
</div></div></div></div>
<div class="modal fade" id="eq_modal"><div class="modal-dialog"><div class="modal-content"><div class="modal-header bg-blue"><button class="close" data-dismiss="modal">&times;</button><h4>REGISTRAR EQUIPAJE</h4></div><div class="modal-body"><div id="eq_pasajero_info" class="alert alert-info"></div><input type="hidden" id="eq_pasaje_id"><div class="row"><div class="col-md-6"><label>Tipo</label><select id="eq_equipaje_tipo" class="form-control" onchange="eqRecalcular()"><option value="INCLUIDO">INCLUIDO / GRATUITO</option><option value="EXTRA">EQUIPAJE EXTRA</option></select></div><div class="col-md-6"><label>Concepto</label><select id="eq_subtipo" class="form-control" onchange="eqRecalcular()"><option value="INCLUIDO">INCLUIDO</option><option value="PIEZA_ADICIONAL">PIEZA ADICIONAL</option><option value="EXCESO_PESO">EXCESO DE PESO</option><option value="ESPECIAL">EQUIPAJE ESPECIAL</option></select></div></div><div class="row" style="margin-top:8px"><div class="col-md-4"><label>Piezas</label><input type="number" min="1" id="eq_cantidad" class="form-control" value="1" oninput="eqRecalcular()"></div><div class="col-md-4"><label>Peso Kg</label><input type="number" min="0" step="0.01" id="eq_peso" class="form-control" value="0" oninput="eqRecalcular()"></div><div class="col-md-4"><label>Importe manual Bs</label><input type="number" min="0" step="0.01" id="eq_importe_manual" class="form-control" value="0" oninput="eqRecalcular()"></div></div><div style="margin-top:8px"><label>Descripción *</label><input id="eq_descripcion" class="form-control" placeholder="Ej.: MALETA NEGRA / TELEVISOR 50 PULGADAS"></div><div class="row" style="margin-top:8px"><div class="col-md-6"><label>Forma de pago</label><select id="eq_forma" class="form-control"><option value="0">-- SIN COBRO --</option><?php foreach($formas_pago as $f){ ?><option value="<?php echo (int)$f['forma_id']; ?>"><?php echo htmlspecialchars($f['forma_nombre']); ?></option><?php } ?></select></div><div class="col-md-6"><label>Importe calculado</label><div class="form-control eq-money" id="eq_total">Bs 0.00</div></div></div><div style="margin-top:8px"><label>Observaciones</label><textarea id="eq_observaciones" class="form-control"></textarea></div><div id="eq_tarifa_info" class="text-muted" style="margin-top:6px"></div></div><div class="modal-footer"><button class="btn btn-default" data-dismiss="modal">Cancelar</button><button class="btn btn-success" id="eq_btn_guardar" onclick="eqGuardar()"><i class="fa fa-save"></i> Registrar e imprimir 2 talones</button></div></div></div></div>
<script>
var EQ_BASE='<?php echo base_url(); ?>', EQ_TARIFA={peso_incluido:20,piezas_incluidas:1,precio_kg_exceso:5,precio_pieza_extra:40}, EQ_PASAJE=0, EQ_PASAJE_DATA=null;
function esc(s){return $('<div>').text(s==null?'':s).html();}
function eqBuscar(){ $.post(EQ_BASE+'equipaje/buscar',{tipo:$('#eq_tipo').val(),valor:$('#eq_valor').val(),fecha:$('#eq_fecha').val()},function(r){if(!r.ok){alert(r.mensaje);return;}var h='';if(!r.resultados.length)h='<span class="text-muted">Sin resultados.</span>';$.each(r.resultados,function(i,p){h+='<div class="eq-result row"><div class="col-md-8"><b>'+esc(p.pasaje_nombre||'SIN NOMBRE')+'</b> · Asiento <b>'+esc(p.asiento_numero||'-')+'</b><br><small>'+esc(p.ruta_nombre||'')+' · '+esc(p.viaje_fechasalida)+' '+esc(p.viaje_horasalida)+' · Equipajes: '+p.equipajes+'</small></div><div class="col-md-4 text-right"><button class="btn btn-primary btn-sm" onclick="eqCargarPasaje('+p.pasaje_id+',false)"><i class="fa fa-eye"></i> VER EQUIPAJE</button> <a class="btn btn-default btn-sm" target="_blank" href="'+EQ_BASE+'equipaje/manifiesto/'+p.viaje_id+'"><i class="fa fa-list"></i> MANIFIESTO</a></div></div>';});$('#eq_resultados').html(h);},'json');}
function eqCargarPasaje(id,abrir){$.getJSON(EQ_BASE+'equipaje/detalle_pasaje/'+id,function(r){if(!r.ok){alert(r.mensaje);return;}EQ_PASAJE=id;EQ_PASAJE_DATA=r.pasaje;EQ_TARIFA=r.tarifa||EQ_TARIFA;$('#eq_pasaje_id').val(id);$('#eq_pasaje_titulo').html('<i class="fa fa-user"></i> '+esc(r.pasaje.pasaje_nombre||'SIN NOMBRE')+' · ASIENTO <b>'+esc(r.pasaje.asiento_numero||'-')+'</b>');$('#eq_pasaje_subtitulo').text((r.pasaje.ruta_nombre||'')+' · '+r.pasaje.viaje_fechasalida+' '+r.pasaje.viaje_horasalida);var h='';if(!r.equipajes.length){h='<div class="alert alert-warning">Este pasajero todavía no tiene equipaje operativo registrado. <button class="btn btn-primary btn-xs" onclick="eqAbrirModal()">REGISTRAR EQUIPAJE</button></div>';}else{var totalImporte=0;h='<div class="table-responsive"><table class="table table-striped table-condensed eq-list"><thead><tr><th>ETIQUETA</th><th>TIPO</th><th>DESCRIPCIÓN</th><th class="text-center">PIEZAS</th><th class="text-right">PESO</th><th class="text-right">IMPORTE</th><th class="text-center">ESTADO</th><th class="text-center">OPCIÓN</th></tr></thead><tbody>';$.each(r.equipajes,function(i,e){var importe=parseFloat(e.equipaje_importe||0),ent=(String(e.equipaje_estado||'').toUpperCase()==='ENTREGADO');totalImporte+=importe;h+='<tr class="'+(ent?'eq-entregado':'')+'"><td><b>'+esc(e.equipaje_numeroetiqueta)+'</b></td><td>'+esc(e.equipaje_tipo)+'</td><td>'+esc(e.equipaje_descripcion)+'</td><td class="text-center">'+e.equipaje_cantidad_piezas+'</td><td class="text-right">'+parseFloat(e.equipaje_peso||0).toFixed(2)+' Kg</td><td class="eq-importe">Bs '+importe.toFixed(2)+'</td><td class="text-center"><span class="'+(ent?'label-entregado':'label-pendiente')+'">'+esc(e.equipaje_estado)+'</span></td><td class="text-center"><a target="_blank" class="btn btn-xs btn-default" href="'+EQ_BASE+'equipaje/imprimir/'+e.equipaje_id+'"><i class="fa fa-print"></i> REIMPRIMIR</a></td></tr>';});h+='</tbody><tfoot><tr><th colspan="5" class="text-right">TOTAL IMPORTE</th><th class="eq-importe">Bs '+totalImporte.toFixed(2)+'</th><th colspan="2"></th></tr></tfoot></table></div>';}$('#eq_lista_equipajes').html(h);$('#eq_pasaje_panel').show();if(abrir)eqAbrirModal();});}
function eqAbrirModal(){if(!EQ_PASAJE){alert('Seleccione primero un pasajero.');return;}$('#eq_pasajero_info').html('<b>'+esc(EQ_PASAJE_DATA.pasaje_nombre||'SIN NOMBRE')+'</b> · ASIENTO '+esc(EQ_PASAJE_DATA.asiento_numero||'-'));$('#eq_equipaje_tipo').val('INCLUIDO');$('#eq_subtipo').val('INCLUIDO');$('#eq_cantidad').val(1);$('#eq_peso').val(0);$('#eq_importe_manual').val(0);$('#eq_descripcion').val('');$('#eq_observaciones').val('');$('#eq_forma').val(0);eqRecalcular();$('#eq_tarifa_info').text('Incluido: '+EQ_TARIFA.piezas_incluidas+' pieza(s), '+EQ_TARIFA.peso_incluido+' Kg · Exceso: Bs '+EQ_TARIFA.precio_kg_exceso+'/Kg · Pieza extra: Bs '+EQ_TARIFA.precio_pieza_extra);$('#eq_modal').modal('show');}
function eqReimprimirTodos(){if(!EQ_PASAJE)return;window.open(EQ_BASE+'equipaje/imprimir_pasaje/'+EQ_PASAJE,'_blank');}
function eqRecalcular(){var tipo=$('#eq_equipaje_tipo').val(),sub=$('#eq_subtipo').val(),q=parseInt($('#eq_cantidad').val()||1),peso=parseFloat($('#eq_peso').val()||0),m=parseFloat($('#eq_importe_manual').val()||0),tot=0;if(tipo==='INCLUIDO'){$('#eq_subtipo').val('INCLUIDO').prop('disabled',true);$('#eq_forma').val(0).prop('disabled',true);}else{$('#eq_subtipo').prop('disabled',false);$('#eq_forma').prop('disabled',false);if(sub==='PIEZA_ADICIONAL')tot=q*parseFloat(EQ_TARIFA.precio_pieza_extra||0);else if(sub==='EXCESO_PESO')tot=Math.max(0,peso-parseFloat(EQ_TARIFA.peso_incluido||0))*parseFloat(EQ_TARIFA.precio_kg_exceso||0);else tot=m;}$('#eq_total').text('Bs '+tot.toFixed(2));}
function eqGuardar(){var w=window.open('about:blank','_blank');$('#eq_btn_guardar').prop('disabled',true);$.post(EQ_BASE+'equipaje/registrar',{pasaje_id:EQ_PASAJE,equipaje_tipo:$('#eq_equipaje_tipo').val(),equipaje_subtipo:$('#eq_subtipo').val(),cantidad_piezas:$('#eq_cantidad').val(),peso:$('#eq_peso').val(),importe_manual:$('#eq_importe_manual').val(),descripcion:$('#eq_descripcion').val(),observaciones:$('#eq_observaciones').val(),forma_id:$('#eq_forma').val()},function(r){$('#eq_btn_guardar').prop('disabled',false);if(!r.ok){if(w)w.close();alert(r.mensaje);return;}$('#eq_modal').modal('hide');if(w)w.location=r.impresion;eqCargarPasaje(EQ_PASAJE,false);},'json');}
function eqBuscarEntrega(){var c=$('#eq_codigo_entrega').val().trim();if(!c){alert('Debe escanear o escribir el código de equipaje.');return;}$.post(EQ_BASE+'equipaje/buscar_etiqueta',{codigo:c},function(r){if(!r.ok){$('#eq_entrega_result').html('<div class="alert alert-danger">'+esc(r.mensaje)+'</div>');return;}var e=r.equipaje,ent=e.equipaje_estado==='ENTREGADO';$('#eq_entrega_result').html('<div class="alert '+(ent?'alert-warning':'alert-success')+'"><b>'+esc(e.equipaje_numeroetiqueta)+'</b> · '+esc(e.pasaje_nombre||'SIN NOMBRE')+' · ASIENTO '+esc(e.asiento_numero||'-')+'<br>'+esc(e.equipaje_descripcion)+'<br>Estado: <b>'+esc(e.equipaje_estado)+'</b>'+(ent?'':'<br><button class="btn btn-primary btn-sm btn-confirmar-entrega" onclick="eqEntregar('+e.equipaje_id+')"><i class="fa fa-check"></i> CONFIRMAR ENTREGA</button>')+'</div>');},'json');}
function eqEntregar(id){if(!confirm('¿Confirmar entrega física de este equipaje?'))return;$.post(EQ_BASE+'equipaje/entregar',{equipaje_id:id},function(r){alert(r.mensaje+(r.hora?' - '+r.hora:''));eqBuscarEntrega();if(EQ_PASAJE)eqCargarPasaje(EQ_PASAJE,false);},'json');}
$('#eq_valor,#eq_codigo_entrega').on('keypress',function(e){if(e.which===13){e.preventDefault();if(this.id==='eq_valor')eqBuscar();else eqBuscarEntrega();}});
<?php if($pasaje_inicial>0){ ?>$(function(){eqCargarPasaje(<?php echo (int)$pasaje_inicial; ?>,false);});<?php } ?>
</script>